<?php require __DIR__.'/common.php';$u=monitor_user();monitor_post();try{[$host,$port]=monitor_target(posted('host'),(int)posted('port'));$d=db();$s=$d->prepare('SELECT COUNT(*) AS n FROM z6_domeny WHERE user_id=?');$s->bind_param('i',$u['id']);$s->execute();if((int)$s->get_result()->fetch_assoc()['n']>=30)throw new InvalidArgumentException('Limit 30 usług na konto.');$s=$d->prepare('INSERT INTO z6_domeny(host,port,user_id) VALUES(?,?,?)');$s->bind_param('sii',$host,$port,$u['id']);$s->execute();$d->close();redirect('monitor.php');}catch(Throwable $e){$_SESSION['monitor_flash']=$e instanceof InvalidArgumentException?$e->getMessage():((int)$e->getCode()===1062?'Ta usługa jest już na Twojej liście.':'Nie udało się dodać usługi.');redirect('dodaj1.php');}
